window.SAQ_PAPER_QUESTIONS["2025-1-north-sydney"]=[{"number":1,"title":"","stemText":"A 24-year-old 32 week pregnant woman is brought in by ambulance to your\ntertiary ED following an MVA. She reports moderate abdominal pain.\n\nHR 150 BP 95/42 RR 25 SpO2 93% on RA T 36.3","parts":[{"id":"a","label":"Part A","prompt":"State 5 (Five) normal physiological changes in pregnancy (5 marks)"},{"id":"b","label":"Part B","prompt":"List 5 (five) complications of abdominal trauma specific to pregnancy (5 marks)"},{"id":"c","label":"Part C","prompt":"State 2 (two) modifications to assessment or management of trauma patients in\nadvanced pregnancy and justify (4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Must have answers from at least 3 body systems</td></tr><tr><td colspan=\"2\">Cardiovascular</td></tr><tr><td></td><td>heart size increases</td></tr><tr><td></td><td>CO increases by 40%</td></tr><tr><td></td><td>HR increases 15 - 20 min by term</td></tr><tr><td></td><td>BP falls 10 - 15mmHg in 2nd trimester</td></tr><tr><td></td><td>90% have systolic murmur</td></tr><tr><td></td><td>asymptomatic pericardial effusion</td></tr><tr><td></td><td>blood volume increases</td></tr><tr><td colspan=\"2\">Haematological</td></tr><tr><td></td><td>RBC mass increases</td></tr><tr><td></td><td>coag factors increase</td></tr><tr><td></td><td>D-dimer elevated, normalises by 4 w post-partum</td></tr><tr><td colspan=\"2\">Respiratory</td></tr><tr><td></td><td>maternal O2 consumption increases by 20 - 40%</td></tr><tr><td></td><td>diaphragm elevated: TLC decreases</td></tr><tr><td></td><td>FRC, RV, ERV decrease</td></tr><tr><td></td><td>MV increases</td></tr><tr><td colspan=\"2\">Gastrointestinal</td></tr><tr><td></td><td>motility decreases</td></tr><tr><td></td><td>predisposed to gallstones</td></tr><tr><td></td><td>insulin resistance</td></tr><tr><td colspan=\"2\">Renal</td></tr><tr><td></td><td>GFR increases by 50%</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">preterm labour</div><div class=\"answer-line\"></div><div class=\"answer-line\">premature rupture of membranes</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td></td><td>preterm labour</td></tr><tr><td></td><td>premature rupture of membranes</td></tr><tr><td></td><td>placental abruption</td></tr><tr><td></td><td>foetal maternal haemorrhage</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":2,"title":"","stemText":"A 78-year-old male presents to your ED with a red painful eye, worsening over\nthe last 3 days.","parts":[{"id":"a","label":"Part A","prompt":"Please list your differential for an acutely painful, red eye (6 marks)"},{"id":"b","label":"Part B","prompt":"Please describe the relevant findings from the patient picture below and interpret your findings by refining your differential diagnosis (6 marks) Describe: (3 marks) Refined Differential: (3 marks)"},{"id":"c","label":"Part C","prompt":"In order to refer to Ophthalmology, please list specific examination findings you must check for before calling: (4 marks)"}],"propPages":["asset:imga20d206e15d765c4b3"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><strong>Model Answer </strong></div><div class=\"answer-line\">Foreign Body / Corneal Abrasion (1)</div><div class=\"answer-line\">Chemical injury (1)</div><div class=\"answer-line\">Acute angle closure Glaucoma (1)</div><div class=\"answer-line\">Inflammation – Iritis / Uveitis (1)</div><div class=\"answer-line\">Infection – Keratitis / Endophthalmitis / Conjunctivitis (3)</div><div class=\"answer-line\">ACI.health.nsw.gov.au – Eye Emergency Manual 3rd ed; 2023</div><div class=\"answer-line\"><strong>Part b (6) </strong></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><strong>Q &amp; A – 2025.1 Fellowship Written Exam – Network 2</strong></div><div class=\"answer-line\"><strong>Describe: (3) </strong></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><strong>Model Answer </strong></div><div class=\"answer-line\">Visual Acuity (1)</div><div class=\"answer-line\">RAPD (1)</div><div class=\"answer-line\">IOP (3)</div><div class=\"answer-line\">Slit Lamp Exam with fluorescin (4)</div><div class=\"answer-line\">ACI.health.nsw.gov.au – Eye Emergency Manual 3rd ed; 2023</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":3,"title":"","stemText":"A 6-year-old male is brought into ED by his parents with ataxia for the last 24\nhours. He has normal vital signs.","parts":[{"id":"a","label":"Part A","prompt":"State four (4) key differentials for his presentation (4 marks)"},{"id":"b","label":"Part B","prompt":"List five (5) “red flag” features you would seek on examination specific to his presentation (5 marks)"},{"id":"c","label":"Part C","prompt":"List three (3) key features of appropriately designed paediatric emergency medicine spaces (3 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Must state toxins, tumour, trauma in differentials, plus one other</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">No marks for abnormal vital signs – they are normal as above</td></tr><tr><td></td><td>Signs of raised intracranial pressure (must give examples/s eg headache worse while</td></tr><tr><td colspan=\"2\">supine, recurrent vomiting, vision loss or diplopia, bradycardia, hypertension or</td></tr><tr><td colspan=\"2\">papilledema) – max 2 marks for features of raised ICP</td></tr><tr><td></td><td>Altered conscious state</td></tr><tr><td></td><td>Focal neurology</td></tr><tr><td></td><td>Meningism</td></tr><tr><td></td><td>Loss of proprioception, vibration sense or tactile discrimination</td></tr><tr><td></td><td>Weakness</td></tr><tr><td></td><td>Abnormal deep tendon reflexes</td></tr><tr><td></td><td>Evidence of trauma</td></tr><tr><td colspan=\"2\"><strong>Q &amp; A – 2025.1 Fellowship Written Exam – Network 2</strong></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">The paediatric area must be easily observed at all times by registered nursing staff</td></tr><tr><td></td><td>The areas dedicated for use by children and young persons should be clearly</td></tr><tr><td colspan=\"2\">designated and furnished and decorated in a manner that is colourful, comfortable</td></tr><tr><td colspan=\"2\">and reassuring for both patients and their parents. Suitable play areas and play</td></tr><tr><td colspan=\"2\">facilities should also be provided.</td></tr><tr><td></td><td>The design of consulting and treatment areas should permit and encourage parents</td></tr><tr><td colspan=\"2\">to remain with their child. The option of family-member presence must be</td></tr><tr><td colspan=\"2\">encouraged for all aspects of ED care.</td></tr><tr><td></td><td>A paediatric zone will require a greater proportion of standard isolation rooms</td></tr><tr><td colspan=\"2\">compared with an acute adult ED zone.</td></tr><tr><td></td><td>The resuscitation area must be fully equipped to manage all types of paediatric</td></tr><tr><td colspan=\"2\">emergencies. Mobile paediatric resuscitation trolleys should be immediately</td></tr><tr><td colspan=\"2\">accessible in any location in which a child could deteriorate. A camera in the</td></tr><tr><td colspan=\"2\">paediatric resuscitation zone is required to communicate with neonatal emergency</td></tr><tr><td colspan=\"2\">transport services.</td></tr><tr><td></td><td>Younger children must have access to nutrition (this includes provision for</td></tr><tr><td colspan=\"2\">breastfeeding).</td></tr><tr><td></td><td>Dedicated space for the assessment of paediatric patients with mental health</td></tr><tr><td colspan=\"2\">conditions is desirable.</td></tr><tr><td></td><td>Adequate space should be available for children/families in crisis, and should include</td></tr><tr><td colspan=\"2\">a private room with suitable supervision by emergency staff.</td></tr><tr><td></td><td>Other reasonable answers acceptable.</td></tr><tr><td colspan=\"2\">Ref ACEM document “Hospital emergency department services for children and young</td></tr><tr><td colspan=\"2\">persons”</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":4,"title":"","stemText":"A 55-year-old woman presents to your emergency department describing\npalpitations and dizziness for the last 12 hours. You assess the patient and interpret her ECG. You diagnose atrial fibrillation with rapid ventricular response.","parts":[{"id":"a","label":"Part A","prompt":"List 4 (four) important risk factors, precipitants or antecedent events associated\nwith paroxysmal AF (4 marks) You decide there is no obvious reversible cause for her AF and consider options for the management of her paroxysmal AF."},{"id":"b","label":"Part B","prompt":"Complete the table below outlining two treatment options followed by one indication and one contraindication for each option (8 marks) Drug and Dose or Specific Indicatio Contraindicati Category Procedure n\n• n\nRate Control Rate Control Rhythm Control Rhythm Control Your attempt at rhythm control was unsuccessful, and you decide to proceed with rate control."},{"id":"c","label":"Part C","prompt":"List 4 (four) important considerations in assessing Atrial Fibrillation Stroke Risk\n(4 marks)"}],"propPages":["asset:imgd2a035d866fa9e3c3b"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Cardiac causes:</div><div class=\"answer-line\">ISCHAEMIC HEART DISEASE/MYOCARDIAL ISCHAEMIA (must include to</div><div class=\"answer-line\">pass)</div><div class=\"answer-line\">Pericarditis</div><div class=\"answer-line\">Hypertension/Hypertensive heart disease</div><div class=\"answer-line\">Cardiomyopathy</div><div class=\"answer-line\">Rheumatic Heart Disease</div><div class=\"answer-line\">Pre-excitation syndromes</div><div class=\"answer-line\">Atrial septal defect, atrial myxoma</div><div class=\"answer-line\"><strong>Q &amp; A – 2025.1 Fellowship Written Exam – Network 2</strong></div><div class=\"answer-line\">Non Cardiac causes:</div><div class=\"answer-line\">Electrolyte Imbalances</div><div class=\"answer-line\">Sepsis/Infection</div><div class=\"answer-line\">PE</div><div class=\"answer-line\">Drug and alcohol intoxication/binge</div><div class=\"answer-line\">COPD</div><div class=\"answer-line\">Thyrotoxicosis</div><div class=\"answer-line\">Lung Cancer</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Category</td><td>Drug and Dose or Indication Contraindication</td></tr><tr><td>Specific Prodecure</td><td></td></tr><tr><td>Rate Control</td><td>Metoprolol 1-5mg Clear onset &lt;48 Haemodynamic</td></tr><tr><td>IV over 2 minutes</td><td>hours instability</td></tr><tr><td>up to max 15mg</td><td></td></tr><tr><td>(oral dosing also</td><td>Structural Heart Bronchospasm</td></tr><tr><td>acceptable in</td><td>Disease with beta</td></tr><tr><td>appropriate</td><td>precluding blockers/allergy to</td></tr><tr><td>doses)</td><td>pharmacologic agent</td></tr><tr><td>cardioversion</td><td></td></tr><tr><td>Rate Control</td><td>Verapamil 5-10mg As above As above</td></tr><tr><td>IV over 5 minutes</td><td>WPW is also a</td></tr><tr><td>contraindication</td><td></td></tr><tr><td>Rhythm Control</td><td>DC Cardioversion Haemodynamic Onset &gt;48 hours or</td></tr><tr><td>150-200J Sync</td><td>instability unknown</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"4\">cardioversion</td></tr><tr><td>Rhythm Control</td><td>Flecainide 2mg/kg</td><td>Proven absence of</td><td>Structural heart</td></tr><tr><td>over 30 minutes</td><td>structural heart</td><td>disease or</td><td></td></tr><tr><td>disease</td><td>unknown</td><td></td><td></td></tr><tr><td colspan=\"4\">Your attempt at rhythm control was unsuccessful, and you decide to proceed</td></tr><tr><td colspan=\"4\">with rate control.</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":5,"title":"","stemText":"You are working a mid-week, dayshift in a large tertiary Emergency Department when local paramedics transmit a 12-lead ECG of a 48-year-old male complaining\n• f severe central chest pain. Over the phone, they report that he is pale and\ndiaphoretic with a GCS of 15 and a systolic blood pressure of 86mmHg.\nHere is the initial 12-lead ECG.","parts":[{"id":"a","label":"Part A","prompt":"Describe and interpret his ECG (4 marks) Five minutes after the initial phone-call, you are notified by paramedics that the patient has deteriorated and is in cardiac arrest with an initial rhythm of ventricular fibrillation (VF). On arrival to ED, he remains in VF having received 8 defibrillations (200J), 4mg adrenaline (intravenous) and amiodarone (300mg intravenous). His arrest occurred 24 minutes ago."},{"id":"b","label":"Part B","prompt":"List 2 (two) strategies you can employ with your defibrillator which may result in\nsuccessful defibrillation (2 marks)"},{"id":"c","label":"Part C","prompt":"List 4 (four) inclusion criteria required for initiating ECMO-CPR in refractory\ncardiac arrest (4 marks)"},{"id":"d","label":"Part D","prompt":"List 2 (two) other (ie. non-AMI) indications for ECMO-CPR (2 marks)"}],"propPages":["asset:imgc633f0ff7cf633ee5f"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><strong>a. Activation of cardiac cath lab for emergent reperfusion.</strong></div><div class=\"answer-line\">2. T-wave inversion (V1-2) and biphasic T-wave V3</div><div class=\"answer-line\">3. Reciprocal ST-segment depression (inferior leads)</div><div class=\"answer-line\">4. Sinus rhythm with atrial ectopics</div><div class=\"answer-line\">5. Pseudo RBBB (RSR-pattern)</div><div class=\"answer-line\"><strong>Q &amp; A – 2025.1 Fellowship Written Exam – Network 2</strong></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">List two (2) strategies you can employ with your defibrillator which may</div><div class=\"answer-line\">result in successful defibrillation (2 marks).</div><div class=\"answer-line\">1. Ensure adequate pad contact</div><div class=\"answer-line\">2. Vector change (repositioning of pads = ideally, AP-position)</div><div class=\"answer-line\">3. Dual sequential defibrillation</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">List four (4) inclusion criteria required for initiating ECMO-CPR in</div><div class=\"answer-line\">refractory cardiac arrest (4 marks).</div><div class=\"answer-line\">Inclusion criteria.</div><div class=\"answer-line\">1. Age 16-70</div><div class=\"answer-line\">2. Witnessed arrest</div><div class=\"answer-line\">3. Immediate CPR (within 5 minutes)</div><div class=\"answer-line\">4. Initial rhythm:</div><div class=\"answer-line\">a. VF/VT</div><div class=\"answer-line\">b. PEA (with ETCO2 &gt;10mmHg on ED arrival)</div><div class=\"answer-line\">5. Able to establish ECMO within 60 minutes of arrest time</div><div class=\"answer-line\">a.<em> Alternate</em>: Arrest to hospital arrival &lt;45 minutes.</div><div class=\"answer-line\"><strong>Q &amp; A – 2025.1 Fellowship Written Exam – Network 2</strong></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">1. Pulmonary embolism</div><div class=\"answer-line\">2. Toxicology (eg. beta- or calcium-channel blocker)</div><div class=\"answer-line\">3. Hypothermia</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":6,"title":"","stemText":"A 19-year-old female presents to your emergency department with a 3 month\nhistory of seizures that are increasing in frequency. She begins seizing as you walk into the bedspace, then the seizure ends without a post ictal period.","parts":[{"id":"a","label":"Part A","prompt":"Name 5 (five) features that are suggestive of psychogenic non-epileptic seizures,\naside from the lack of post-ictal period. (5 marks) Her seizure terminates without intervention. She has also had 3 months worth of worsening weakness to the left half of her body which intermittently prevents her from walking."},{"id":"b","label":"Part B","prompt":"Describe 5 (five) examination findings suggestive of a functional neurological\ndisorder. (5 marks)"},{"id":"c","label":"Part C","prompt":"List 4 (four) differential diagnoses for this presentation. (4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">a. Prolonged duration (esp &gt;5 mins)</div><div class=\"answer-line\">b. Fluctuating course / waxing and waning</div><div class=\"answer-line\">c. Side to side movements</div><div class=\"answer-line\">d. Pelvic thrusting</div><div class=\"answer-line\">e. Crying during ictus</div><div class=\"answer-line\">f.</div><div class=\"answer-line\">Forced eye closure</div><div class=\"answer-line\">g. Recall of events during ictus</div><div class=\"answer-line\">h. Responding to external stimuli during seizure (alleviated / worsened</div><div class=\"answer-line\">seizure)</div><div class=\"answer-line\">i.</div><div class=\"answer-line\">No tongue biting / incontinence</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\"><strong>Q &amp; A – 2025.1 Fellowship Written Exam – Network 2</strong></td></tr><tr><td colspan=\"2\">a. Inconsistent neurological signs</td></tr><tr><td colspan=\"2\">b. Variation of neurological signs – tremor frequency/rhythm/axis</td></tr><tr><td colspan=\"2\">c. Hoover’s sign (absent contralateral hip extension on hip flexion testing)</td></tr><tr><td colspan=\"2\">d. Give way weakness</td></tr><tr><td colspan=\"2\">e. Non anatomical sensory loss</td></tr><tr><td>f.</td><td>Fluctuating sensory deficits between examinations</td></tr><tr><td colspan=\"2\">g. Improvement in signs with distraction</td></tr><tr><td colspan=\"2\">h. Tremor entrainment (matches rhythm of unaffected limb when moved</td></tr><tr><td colspan=\"2\">rhythmically)</td></tr><tr><td>i.</td><td>Knees buckle without causing falls/injuries</td></tr><tr><td>j.</td><td>Exaggerated compensatory movements (Astasia-abasia) eg flailing</td></tr><tr><td colspan=\"2\">arms</td></tr><tr><td colspan=\"2\">k. Dragging monoplegic gait</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">a. Epilepsy</div><div class=\"answer-line\">b. SOL (tumour/ICH)</div><div class=\"answer-line\">c. MS</div><div class=\"answer-line\">d. CVA</div><div class=\"answer-line\">e. Metabolic – Electrolyte/glucose disturbance</div><div class=\"answer-line\">f.</div><div class=\"answer-line\">Cardiac – arrhythmia/long QT</div><div class=\"answer-line\">g. Drug intoxication/withdrawal</div><div class=\"answer-line\">h. Eclampsia</div><div class=\"answer-line\">i.</div><div class=\"answer-line\">Toxidromes</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":7,"title":"","stemText":"A 27-year old male presents to ED with a headache, fever photophobia.\nYou are concerned she might have meningitis.","parts":[{"id":"a","label":"Part A","prompt":"You are asked to teach a medical student how to assess if the patient is brudzinski\n• r kernig positive. Please explain how to examine for each of these signs and what\npositive would look like. (2 marks) Sign How to examine Positive Finding Brudzinski Kernig You decide that she needs a lumbar puncture."},{"id":"b","label":"Part B","prompt":"List 5 (five) contraindications to performing a lumbar puncture. (5 marks)"},{"id":"c","label":"Part C","prompt":"List what tests you want to order for the CSF. (2 marks)"},{"id":"d","label":"Part D","prompt":"You identify no contraindications and proceed with the LP. Interpret this CSF result (1 Mark) CSF\n\nWCC\n700 (predominance polymorphs) RCC Protein 1.2 g/L\n\nGlucose\n2 mmol/L"},{"id":"e","label":"Part E","prompt":"List 4 (four) medications you might use to treat meningitis. (4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>brudinski or kernig positive. Please explain how to examine for each of these</td><td>signs and what positive would look like (Ref: UpToDate - 2 marks).</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Anticoagulant therapy</div><div class=\"answer-line\"></div><div class=\"answer-line\">Bleeding diathesis</div><div class=\"answer-line\"></div><div class=\"answer-line\">Suspected DIC (including evolving petechial/purpuric rash)</div><div class=\"answer-line\"></div><div class=\"answer-line\">Chiari malformation</div><div class=\"answer-line\"></div><div class=\"answer-line\">Localised infection over lumbar region</div><div class=\"answer-line\"></div><div class=\"answer-line\">Significant cardiorespiratory compromise that may further deteriorate</div><div class=\"answer-line\"></div><div class=\"answer-line\">whilst positioning for LP</div><div class=\"answer-line\">Possible raised ICP that required CT brain first to rule out (focal</div><div class=\"answer-line\"></div><div class=\"answer-line\">neurological signs, papilloedema, new onset seizures, rapidly</div><div class=\"answer-line\">deteriorating conscious state)</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Cell count (glucose and protein)</div><div class=\"answer-line\"></div><div class=\"answer-line\">CSF gram stain and culture</div><div class=\"answer-line\"></div><div class=\"answer-line\">Viral PCR (eg HSV, VZV)</div><div class=\"answer-line\"></div><div class=\"answer-line\">Meningococcal, Pneumoccocal PCRs</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">You decide that she needs a lumbar puncture. What are some</div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>WCC</td><td>700 (predominance polymorphs)</td></tr><tr><td>RCC</td><td>3</td></tr><tr><td>Protein</td><td>1.2 g/L</td></tr><tr><td>Glucose</td><td>2 mmol/L</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false,"investigationTables":[{"id":"investigation-1","title":"CSF results","headers":["Test","Result"],"rows":[["CSF",""],["WCC","700 (predominance polymorphs)"],["RCC","3"],["Protein","1.2 g/L"],["Glucose","2 mmol/L"]]}]},{"number":8,"title":"","stemText":"A 45-year-old female wheelchair bound patient is BIBA feeling generally unwell,\nsweaty, complaining of a headache.","parts":[{"id":"a","label":"Part A","prompt":"At what level and above spinal injury would you be worried about autonomic dysreflexia. (1 mark)"},{"id":"b","label":"Part B","prompt":"List 5 (five) common signs and symptoms of autonomic dysreflexia. (5 marks)"},{"id":"c","label":"Part C","prompt":"List 2 (two) common causes that trigger autonomic dysreflexia. (2 marks)"},{"id":"d","label":"Part D","prompt":"Outline 2 (two) pharmaceutical and 2 (two) non pharmaceutical steps to managing\nautonomic dysreflexia. (4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">sweaty, complaining of a headache. (Total 12 marks)</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">dysreflexia? (Ref: ACI Autonomic dysreflexia guideline – Mark 1)</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">T6 and above</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"empty-state\">The supplied marking resource did not contain extractable text for this part.</div></section></div>","answerExtractionVerified":false,"answerSourceRetained":false},{"number":9,"title":"","stemText":"A new mother attends your suburban ED with her five day old baby, Dimitrios.\nDimitrios was born at 36+5 gestation via an assisted vaginal delivery, weighing\n3080g. He was deemed safe for discharge on day three of life. His mother is concerned because he is not breast-feeding as well as usual and seems to be more lethargic. In the past 24 hours, she has felt that his skin has become more yellow in colour.\nHis observations in ED:\n\nHR 178\n\nRR 56\n\nSats 98% RA\n\nTemp 37.8\n\nBSL 3.1\n\nWeight 2.65kg","parts":[{"id":"a","label":"Part A","prompt":"List 6 (six) potential differentials for Dimitrios’ presentation (6 marks)"},{"id":"b","label":"Part B","prompt":"Aside from total serum bilirubin, list and justify 7 (seven) additional investigations you consider MOST RELEVANT to perform in the ED. (7 marks) The total serum bilirubin returns as 17mg/dL."},{"id":"c","label":"Part C","prompt":"List the definitive management of Dimitrios (4 marks)"},{"id":"d","label":"Part D","prompt":"Dimitrios has a rapidly rising serum bilirubin level and is still in your ED. What should be considered now in his management? (1 mark)"}],"propPages":["asset:img6d79be9e393053c4d9"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">List six (6) potential differentials for Dimitrios’ presentation</div><div class=\"answer-line\">----------------------------------------------------------------------------------------------------------------</div><div class=\"answer-line\">----------------------------------------------------------------------------------------------------------------</div><div class=\"answer-line\">----------------------------------------------------------------------------------------------------------------</div><div class=\"answer-line\">----------------------------------------------------------------------------------------------------------------</div><div class=\"answer-line\">----------------------------------------------------------------------------------------------------------------</div><div class=\"answer-line\">----------------------------------------------------------------------------------------------------------------</div><div class=\"answer-line\"><em>6 marks</em></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Aside from total serum bilirubin, list and justify seven (7) additional</div><div class=\"answer-line\">investigations you consider MOST RELEVANT to perform in the ED</div><div class=\"answer-line\">----------------------------------------------------------------------------------------------------------------</div><div class=\"answer-line\">----------------------------------------------------------------------------------------------------------------</div><div class=\"answer-line\">----------------------------------------------------------------------------------------------------------------</div><div class=\"answer-line\">----------------------------------------------------------------------------------------------------------------</div><div class=\"answer-line\">----------------------------------------------------------------------------------------------------------------</div><div class=\"answer-line\">----------------------------------------------------------------------------------------------------------------</div><div class=\"answer-line\"><em>7 marks</em></div><div class=\"answer-line\"><strong>Q &amp; A – 2025.1 Fellowship Written Exam – Network 2</strong></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">List the definitive management of Dimitrios</div><div class=\"answer-line\">----------------------------------------------------------------------------------------------------------------</div><div class=\"answer-line\">----------------------------------------------------------------------------------------------------------------</div><div class=\"answer-line\">----------------------------------------------------------------------------------------------------------------</div><div class=\"answer-line\">----------------------------------------------------------------------------------------------------------------</div><div class=\"answer-line\"><em>4 marks</em></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Dimitrios has a rapidly rising serum bilirubin level and is still in your ED. What</td></tr><tr><td colspan=\"2\">should be considered now in his management?</td></tr><tr><td colspan=\"2\">----------------------------------------------------------------------------------------------------------------</td></tr><tr><td colspan=\"2\"><em>1 mark</em></td></tr><tr><td colspan=\"2\"><em><strong>Total Marks 18</strong></em></td></tr><tr><td colspan=\"2\"><strong>Q &amp; A – 2025.1 Fellowship Written Exam – Network 2</strong></td></tr><tr><td colspan=\"2\"><strong>Answers</strong></td></tr><tr><td colspan=\"2\"><strong>a.</strong></td></tr><tr><td></td><td><strong>Serious bacterial infection/sepsis</strong></td></tr><tr><td></td><td>Dehydration</td></tr><tr><td></td><td>Physiological jaundice</td></tr><tr><td></td><td>Breast milk jaundice</td></tr><tr><td></td><td>ABO incompatibility</td></tr><tr><td></td><td>Haemolysis</td></tr><tr><td></td><td>Biliary atresia</td></tr><tr><td></td><td>Metabolic (eg G6PD, fructose intolerance)</td></tr><tr><td></td><td>Hepatitis</td></tr><tr><td></td><td>Bowel obstruction</td></tr><tr><td></td><td>Breakdown of extravasated blood (eg cephalhaematoma, NAI,</td></tr><tr><td colspan=\"2\">polycythemia)</td></tr><tr><td></td><td>Congenital disease (TORCH infection, Gilbert’s, Crigler Najjar)</td></tr><tr><td></td><td>Hypothyroidism</td></tr><tr><td colspan=\"2\"><strong>b.</strong></td></tr><tr><td></td><td>FBC – evidence of hemolysis/marker of infection/evidence of</td></tr><tr><td colspan=\"2\">dehydration</td></tr><tr><td></td><td>Blood film - evidence of hemolysis/marker of infection/evidence of</td></tr><tr><td colspan=\"2\">dehydration</td></tr><tr><td></td><td>Reticulocyte count – evidence of haemolysis</td></tr><tr><td></td><td>Cultures (Blood/urine/CSF) culture – seeking infectious aetiology</td></tr><tr><td colspan=\"2\">(award ½ point each if listed separately)</td></tr><tr><td></td><td>Conjugated (direct) and unconjugated (indirect) bilirubin – determine</td></tr><tr><td colspan=\"2\">if biliary obstruction (award 1 point ONLY if both are listed)</td></tr><tr><td></td><td>Maternal and foetal blood group – evidence of  ABO/Rh</td></tr><tr><td colspan=\"2\">incompatibility causing haemolysis</td></tr><tr><td></td><td>Direct Coombs – seeking antibodies causing haemolysis</td></tr><tr><td></td><td>G6PD screen – screen as potential cause of haemolysis</td></tr><tr><td></td><td>EUC – screen for hydration status in poor feeding</td></tr><tr><td colspan=\"2\">Less relevant initial investigations for this case:</td></tr><tr><td></td><td>TORCH screen – screen for congenital infection</td></tr><tr><td></td><td>Head ultrasound – screen for subgaleal haematoma or similar</td></tr><tr><td></td><td>LFT – screen for hepatitis/biliary obstruction</td></tr><tr><td></td><td>TFT – screen for thyroid disease</td></tr><tr><td></td><td>CRP – additional screen to assist in identifying infection</td></tr><tr><td></td><td>VBG (lactate) – additional screen to assist in identifying infection</td></tr><tr><td colspan=\"2\"><strong>Q &amp; A – 2025.1 Fellowship Written Exam – Network 2</strong></td></tr><tr><td></td><td>Ammonia – initial screen for metabolic disease</td></tr><tr><td></td><td>Albumin – only really needed if abnormal ratio of bilirubin</td></tr><tr><td colspan=\"2\"><strong>c.</strong></td></tr><tr><td></td><td>IV antimicrobials (below combinations are acceptable)</td></tr><tr><td colspan=\"2\">Cefotaxime 50mg/kg + ampicillin 100mg/kg + Gentamicin</td></tr><tr><td colspan=\"2\">o</td></tr><tr><td colspan=\"2\">5mg/kg</td></tr><tr><td colspan=\"2\">OR</td></tr><tr><td colspan=\"2\">Cefotaxime 50mg/kg + benzylpenicillin 60mg/kg</td></tr><tr><td colspan=\"2\">o</td></tr><tr><td colspan=\"2\">Either of above may be +/- Aciclovir 20mg/kg</td></tr><tr><td colspan=\"2\">o</td></tr><tr><td></td><td>Fluid/nutritional support (below combinations are acceptable)</td></tr><tr><td colspan=\"2\">IVF – 0.45% NaCl +10% dextrose +/- 10mmol KCl in</td></tr><tr><td colspan=\"2\">o</td></tr><tr><td colspan=\"2\">500ml – 13ml/hr</td></tr><tr><td colspan=\"2\">OR</td></tr><tr><td colspan=\"2\">NGT – EBM 13ml/hr</td></tr><tr><td colspan=\"2\">o</td></tr><tr><td></td><td>Phototherapy as above treatment line</td></tr><tr><td></td><td>Retrieval to NICU/closest facility with inpatient paediatric</td></tr><tr><td colspan=\"2\">services</td></tr><tr><td colspan=\"2\"><strong>d. </strong></td></tr><tr><td colspan=\"2\">Exchange transfusion</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":10,"title":"","stemText":"A Heavily intoxicated 42-year-old male patient is being treated in an urban\nEmergency Department late at night after a motor cycle accident. He has the following Xray taken.","parts":[{"id":"a","label":"Part A","prompt":"What would be your immediate management of this patients arm injury? (4 marks)"},{"id":"b","label":"Part B","prompt":"After immediate management, what immobilisation would you apply to this patient. You are training your registrar in the process. Please describe exactly how you would undertake immobilising this patient. (3 marks)"},{"id":"c","label":"Part C","prompt":"List 3 (three) potential neurovascular complications of this injury? (3 marks)"},{"id":"d","label":"Part D","prompt":"List four (4) potential complications from the immobilisation itself? (4 marks)"}],"propPages":["asset:img1e4da63d6472b44a75"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Answer: Check for injury to nerves and blood vessels/ assess neurovascular</div><div class=\"answer-line\">status</div><div class=\"answer-line\">Check if injury is open. If open given IV antibiotic cover and ensure ADT</div><div class=\"answer-line\">Immediate input from orthopaedic team</div><div class=\"answer-line\">Analgesia (not procedural sedation as patient is heavily intoxicated)</div><div class=\"answer-line\">Attempted reduction of elbow dislocation</div><div class=\"answer-line\">Immobilisation with temporary cast until surgical management</div><div class=\"answer-line\"><em>1 mark for each of the above to a maximum of 4 marks </em></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">stocking underneath (first layer)</div><div class=\"answer-line\">Layer of soft material</div><div class=\"answer-line\">Lay out plaster from roll into sheets</div><div class=\"answer-line\">Length of sheets should be measured against patient</div><div class=\"answer-line\">Cut hand end to fit line of fingers</div><div class=\"answer-line\">Dip plaster in cool water, never hot</div><div class=\"answer-line\">Lay plaster on volar side of arm and mould to patient</div><div class=\"answer-line\">Apply bandage over the top</div><div class=\"answer-line\">Sling and elevation</div><div class=\"answer-line\"><em>0.5 marks for each point to a max of 2.5 marks </em></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Injury to the brachial artery</div><div class=\"answer-line\">Injury to the ulnar nerve injury</div><div class=\"answer-line\">Injury to the medium nerve injury</div><div class=\"answer-line\">Posterior interosseous nerve (PIN) injury</div><div class=\"answer-line\"><em>0.5 marks each to a maximum of 1.5 marks </em></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Hair torniquet, pressure sore, impaired arterial supply, impaired venous</div><div class=\"answer-line\">return, neuropraxia, pain secondary to cast pressure points, DVT/PE, tissue</div><div class=\"answer-line\">necrosis and infection, joint stiffness</div><div class=\"answer-line\"><em>0.5 marks each to a maximum of 3.5 marks </em></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":11,"title":"","stemText":"A 66yr old male presents to your metropolitan ED after falling and injuring his\nLEFT foot; his foot got caught in a pothole and twisted awkwardly during the fall. He has been unable to weight bear since. His foot is swollen, bruised and he appears uncomfortable. He has no other injuries from the fall and is haemodynamically stable. His only PMHx is that of hypertension for which he takes perindopril. He has no allergies and is on no other medications. His Xrays are shown below.","parts":[{"id":"a","label":"Part A","prompt":"List 4 (four) abnormalities on this Xray. (4 marks)"},{"id":"b","label":"Part B","prompt":"Outline 2 (two) assessment and 2 (two) management priorities for this\npatient. (4 marks)"},{"id":"c","label":"Part C","prompt":"List four (4) potential complications that this patient may encounter from this injury. (4 marks)"}],"propPages":["asset:img482e9c403d7ab1c429","asset:img87129c2962b5106e14","asset:imgc5155958d611df5675"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">SAQ Foot Injury - CA</div><div class=\"answer-line\">A 66yr old male presents to your metropolitan ED after falling and injuring his LEFT foot; his</div><div class=\"answer-line\">foot got caught in a pothole and twisted awkwardly during the fall.</div><div class=\"answer-line\">He has been unable to weight bear since. His foot is swollen, bruised and he appears</div><div class=\"answer-line\">uncomfortable. <strong>He has no other injuries from the fall and is haemodynamically stable.</strong> His</div><div class=\"answer-line\">only PMHx is that of hypertension for which he takes perindopril. He has no allergies and is</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">A 66yr old male presents to your metropolitan ED after falling and injuring his LEFT foot; his</div><div class=\"answer-line\">foot got caught in a pothole and twisted awkwardly during the fall.</div><div class=\"answer-line\">He has been unable to weight bear since. His foot is swollen, bruised and he appears</div><div class=\"answer-line\">uncomfortable. <strong>He has no other injuries from the fall and is haemodynamically stable.</strong> His</div><div class=\"answer-line\">only PMHx is that of hypertension for which he takes perindopril. He has no allergies and is</div><div class=\"answer-line\">on no other medications.</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><strong>Q &amp; A – 2025.1 Fellowship Written Exam – Network 2</strong></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":12,"title":"","stemText":"Angelina has brought her 2-year-old daughter, Shiloh, to your rural ED with\nconcerns for limping. She does not recall any trauma but she has been at daycare all day.","parts":[{"id":"a","label":"Part A","prompt":"Outline six (6) features in the history that would raise concerns for significant pathology. (6 marks)"},{"id":"b","label":"Part B","prompt":"Outline four (4) features in your examination that would raise concerns for significant pathology (4 marks) Examination Feature Pathology Shiloh examines very well, with normal observations and no fever. She has a slight limp which improves after some Nurofen."},{"id":"c","label":"Part C","prompt":"List 2 (two) differential diagnosis. (2 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Answer</div><div class=\"answer-line\"><strong>1. Don’t accept trauma </strong></div><div class=\"answer-line\">Symptoms over a week</div><div class=\"answer-line\">Complete NWB</div><div class=\"answer-line\">Severe pain / functional limitation</div><div class=\"answer-line\">NOCTURNAL pain</div><div class=\"answer-line\">Changes to bladder or bowel</div><div class=\"answer-line\">Systemic symptoms– fever. Rigors. Rash</div><div class=\"answer-line\">Constitutional symptoms – wt loss, lethargy, bleeding</div><div class=\"answer-line\">Something about NAI fine – like multiple presentations with</div><div class=\"answer-line\">unexplained injury</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">EXAMINATION FEATURE</div><div class=\"answer-line\">PATHOLOGY</div><div class=\"answer-line\">Bruising, pallor , petechiae- cancer</div><div class=\"answer-line\">Toxic/ fever/ haemodynamic instability – septic arthritis /OM</div><div class=\"answer-line\"><strong>Q &amp; A – 2025.1 Fellowship Written Exam – Network 2</strong></div><div class=\"answer-line\">NWB despite analgesia – SA/ CANCER/OM</div><div class=\"answer-line\">Multiple bruises/ TEN4FACES – NAI</div><div class=\"answer-line\">Petechia/ Abdo pain/ HTN- HSP</div><div class=\"answer-line\">Swelling and deformity- trauma, neoplasm</div><div class=\"answer-line\">Pain ++ in single joint on moving – SA, JIA</div><div class=\"answer-line\">Cellulitis/ creptitus – nec fasc or invasive soft tissue</div><div class=\"answer-line\">Pale pulseless- vaso-occulsive crisis – sickle or vasculitis</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Answer</div><div class=\"answer-line\">Transient synovitis/ myositis/ toddler fracture</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":13,"title":"","stemText":"An 8-month-old boy presents to your tertiary ED with noisy breathing. He is\npreviously well with normal growth and development.\nHe is given a category 2 due to his mild work of breathing and the triage nurse\nremarks that ‘he’s a crouper’","parts":[{"id":"a","label":"Part A","prompt":"Aside from croup, list 3 (three) differential diagnosis for his presentation and historical or clinical features that may be supportive (6 marks)"},{"id":"b","label":"Part B","prompt":"On further history you ascertain that he is immunised and has had a snotty nose and mum has noticed a barking cough. There are no other red flags in the history. His\n• bs are RR 42, sPo2 98% HR 140 Cap refil less than 3 seconds, Temp 37.8 What\nexamination features would concern you for severe croup. (3 marks)"},{"id":"c","label":"Part C","prompt":"You decide he has severe but not life threatening croup. Outline your initial management of this patient. (3 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">historical or clinical  features that may be supportive  (6)</td></tr><tr><td colspan=\"2\">3 of</td></tr><tr><td>-</td><td>Inhaled FB- MUST HAVE – sudden chocking event, unsupervised,</td></tr><tr><td colspan=\"2\">developmental congruent</td></tr><tr><td>-</td><td>Anaphylaxis – allergens, swelling, urticarial</td></tr><tr><td>-</td><td>Epiglottitis – high fevers, unimmunised , drooling, absent cough</td></tr><tr><td>-</td><td>Bacterial Tracheitis – unwell, rapid onset , tender trachea, thick mucusy</td></tr><tr><td colspan=\"2\">cough</td></tr><tr><td>-</td><td>Deep space neck infection/ Peritonsillar abscess- neck stiffness, drooling,</td></tr><tr><td colspan=\"2\">unwell</td></tr><tr><td>-</td><td>Burns – exposure, soot elsewhere</td></tr><tr><td>-</td><td>Laryngomalacia – not sudden onset, well child , possible poor weight</td></tr><tr><td colspan=\"2\">gain</td></tr><tr><td>-</td><td>Subglottic stenosis – history of long intubation</td></tr><tr><td>-</td><td>Post intubation –recent procedure</td></tr><tr><td>-</td><td>Bronchiolitis –grunting – viral prodrome,</td></tr><tr><td colspan=\"2\"><strong>Q &amp; A – 2025.1 Fellowship Written Exam – Network 2</strong></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">snotty nose and mum has noticed a barking cough. There are no other</td></tr><tr><td colspan=\"2\">red flags in the history.</td></tr><tr><td colspan=\"2\">His obs are RR 42, sPo2 98% HR 140 Cap refil less than 3 seconds, Temp</td></tr><tr><td colspan=\"2\">37.8</td></tr><tr><td colspan=\"2\">What examination features would concern you for severe croup (3)</td></tr><tr><td>-</td><td>Colour change- pale, mottled, cyanotic</td></tr><tr><td>-</td><td>Reduced GCS, agitation, drowsy</td></tr><tr><td>-</td><td>Persistent stridor at rest</td></tr><tr><td>-</td><td>Biphasic stridor</td></tr><tr><td>-</td><td>Stridor getting softer</td></tr><tr><td>-</td><td>Bradyapnoea or tachypnoea</td></tr><tr><td>-</td><td>SCR/ TT/ intercostal recession</td></tr><tr><td>-</td><td>Poor resp effort</td></tr><tr><td colspan=\"2\">Hypoxiaemia</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">initial management of this patient (3)</div><div class=\"answer-line\">Keep calm, with parent etc, minimise unnecessary interventions , resus</div><div class=\"answer-line\">Nebulised adrenaline 5mg 1in 1000</div><div class=\"answer-line\">Dexamethasone 0.6mg/kg</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":14,"title":"","stemText":"During a week-long heatwave, a 63-year-old woman is brought to your ED by her daughter who visited her and found her confused and complaining of a headache She has a background recurrent UTIs and bladder spasms and she is\n• n oxybutynin.\n\nObservations:\n\nHR 125 bpm\n\nBP 95/60\n\nTemp 38.9","parts":[{"id":"a","label":"Part A","prompt":"Provide a definition of heatwave. (2 marks)"},{"id":"b","label":"Part B","prompt":"List 3 (three) medications from 3 (three) different classes that may require dose\nmodification during a heatwave. Provide a brief pharmacological explanation. (6 marks)"},{"id":"c","label":"Part C","prompt":"Apart from non-exertional heat stroke, provide 4 (four) differential diagnoses from 4 (four) different categories for the confused febrile patient (4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">There is no universally accepted definition. ACEM uses the Australian Bureau</div><div class=\"answer-line\">of Meteorology definition “when the maximum and minimum temperatures</div><div class=\"answer-line\">are unusually hot over a three-day period” (ACEM Heat Health Resource). For</div><div class=\"answer-line\">marking, accept a commonsense definition encompassing concepts of</div><div class=\"answer-line\">prolonged period and hotter temperatures than normal for that location.</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Observations:</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Anticholinergics - amitriptyline, dothiepin, promethazine, doxylamine,</div><div class=\"answer-line\">chlorpromazine , prochlorperazine, hyoscine, oxybutynin, olanzapine - cause</div><div class=\"answer-line\">decreased sweating</div><div class=\"answer-line\">Diuretics - frusemide, hydrochlorothiazide, aldosterone, alcohol - cause</div><div class=\"answer-line\">dehydration</div><div class=\"answer-line\">less sweating</div><div class=\"answer-line\">→</div><div class=\"answer-line\">Antipsychotics - clozapine, olanzapine, quetiapine, risperidone - cause</div><div class=\"answer-line\">increased heat production</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":15,"title":"","stemText":"While on shift, one of your juniors prescribed penicillin to a penicillin allergic patient who then has an anaphylactic reaction. They required one dose of adrenaline but are stable and well now. You perform open disclosure with the patient.","parts":[{"id":"a","label":"Part A","prompt":"State 4 (four) elements of open disclosure. (4 marks)"},{"id":"b","label":"Part B","prompt":"List 3 (three) systems or process factors that may have contributed to this event. (3\nmarks) Staff are very fatigued in the department on your shift - there has been significant\naccess block for the last 2 weeks."},{"id":"c","label":"Part C","prompt":"List 5 (five) strategies proposed by ACEM to address access block. (5 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">inform pt asap</td></tr><tr><td colspan=\"2\"><strong>Q &amp; A – 2025.1 Fellowship Written Exam – Network 2</strong></td></tr><tr><td></td><td>briefly establish facts surrounding adverse event</td></tr><tr><td></td><td>express sincere regret and concern for pt&#x27;s welfare</td></tr><tr><td></td><td>acknowledge impact on pt</td></tr><tr><td></td><td>provide info about what happened</td></tr><tr><td></td><td>explain potential consequences of event on them</td></tr><tr><td></td><td>explain steps being taken to minimise harm to them from event</td></tr><tr><td></td><td>advise that full investigation will occur</td></tr><tr><td></td><td>validate pt&#x27;s right to feel how they do</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">incomplete medical documentation</td></tr><tr><td></td><td>miscommunication between staff and patient</td></tr><tr><td></td><td>time pressures/increased workload for staff</td></tr><tr><td></td><td>lack of medication checking process or not performed correctly</td></tr><tr><td></td><td>lack of allergy checking process</td></tr><tr><td></td><td>staff fatigue</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">A whole-of-hospital and whole-of-system approach:</td></tr><tr><td>o</td><td>Mandatory notification must be made to the hospital executive for any</td></tr><tr><td colspan=\"2\">patient with an emergency department length of stay greater than 12</td></tr><tr><td colspan=\"2\">hours.</td></tr><tr><td>o</td><td>Mandatory notification must be made to the relevant Health Minister for</td></tr><tr><td colspan=\"2\">any patient with an emergency department length of stay greater than 24</td></tr><tr><td colspan=\"2\">hours.</td></tr><tr><td></td><td>Increasing hospital and alternative care capacity, including</td></tr><tr><td>o</td><td>Increases in physical inpatient bed capacity of public hospitals</td></tr><tr><td>o</td><td>Implementing over-capacity protocols to share the patient load more</td></tr><tr><td colspan=\"2\">equally throughout the hospital</td></tr><tr><td>o</td><td>Improving, and transparent, bed management practices</td></tr><tr><td>o</td><td>Extending time-based targets, which currently apply to the ED, to inpatient</td></tr><tr><td colspan=\"2\">clinical units</td></tr><tr><td>o</td><td>Extending inpatient services outside of normal business hours, for</td></tr><tr><td colspan=\"2\">example, increasing the availability of radiology services over weekends</td></tr><tr><td>o</td><td>Increasing inpatient staff specialists and/or senior decision makers</td></tr><tr><td colspan=\"2\">working after hours and on weekends to ensure inpatient beds are made</td></tr><tr><td colspan=\"2\">available in a timely and clinically appropriate fashion.</td></tr><tr><td></td><td>Delivering improved care in the community to reduce reliance on the hospital</td></tr><tr><td colspan=\"2\">system eg HITH</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":16,"title":"","stemText":"A 43 year old female presents with severe abdominal pain after having egg\nharvesting for IVF 4 days prior. She also has nausea and vomiting and feels short\n• f breath.","parts":[{"id":"a","label":"Part A","prompt":"List five (5) main risk factors for ovarian hyperstimulation syndrome? (5 marks)"},{"id":"b","label":"Part B","prompt":"You are concerned she has either severe or critical severity OHSS. List five (5) complications of severe or critical OHSS (5 marks)"},{"id":"c","label":"Part C","prompt":"The patient tells you she is planning on getting the fresh embryo transferred this week. What do you advise and why? (2 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">(5)</div><div class=\"answer-line\">PCOS</div><div class=\"answer-line\">Hypogonadotrophic hypogonadism</div><div class=\"answer-line\">Young age</div><div class=\"answer-line\">Low BMI</div><div class=\"answer-line\">High ovarian volume and high antral follicle count on baseline scan</div><div class=\"answer-line\">High AMH</div><div class=\"answer-line\">High treatment doses of FSH</div><div class=\"answer-line\">Rapidly rising or high oestrogen levels</div><div class=\"answer-line\">Large number of oocytes collected (&gt;17)</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">complications of severe or critical OHSS? (5)</div><div class=\"answer-line\">DVT</div><div class=\"answer-line\">PE</div><div class=\"answer-line\">Arterial thrombosis</div><div class=\"answer-line\">IJV thrombosis and stroke</div><div class=\"answer-line\">AKI</div><div class=\"answer-line\">ARDS</div><div class=\"answer-line\">Cerebral oedema</div><div class=\"answer-line\">Ovarian torsion</div><div class=\"answer-line\">Ileus</div><div class=\"answer-line\">Ascities</div><div class=\"answer-line\">Pericardial effusion</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">transferred this week. What do you advise and why? (2)</div><div class=\"answer-line\">OHSS is self limiting but exacerbated by pregnancy. It would be far too dangerous to transfer the</div><div class=\"answer-line\">embryo. She will have to freeze the embryo and transfer once she has recovered.</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":17,"title":"","stemText":"A 22-year-old male presents to the Emergency Department with a painful right\nankle after an inversion injury while sliding into homebase playing baseball. He is unable to weight bear, and his foot appears deformed.","parts":[{"id":"a","label":"Part A","prompt":"Describe the findings in the attached photograph and accompanying Xray. (3 marks)"},{"id":"b","label":"Part B","prompt":"Outline your stepwise approach to the emergency management of this injury. (6 marks)"},{"id":"c","label":"Part C","prompt":"List 3 (three) complications associated with this injury. (3 marks)"}],"propPages":["asset:img3069dab192d1f6a4fc","asset:img0f3975c69ba73aa1b6"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Summary diagnosis</div><div class=\"answer-line\">Clinical findings – closed / area at risk for skin necrosis / distal</div><div class=\"answer-line\">perfusion appears intact</div><div class=\"answer-line\">Xray findings – disruption of Talo-navicular and Talo-calcaneal</div><div class=\"answer-line\">joints</div><div class=\"answer-line\">Closed right sided medial subtalar dislocation</div><div class=\"answer-line\">Right foot locked in supination, heel displaced medially and forefoot</div><div class=\"answer-line\">plantarflexed and adducted. Blanching of the skin over the lateral aspect of the</div><div class=\"answer-line\">foot (Head of talus displaced laterall), foot appears pink and otherwise well</div><div class=\"answer-line\">perfused</div><div class=\"answer-line\">Xrays show medial subtalar dislocation   - AP view medial displacement of the</div><div class=\"answer-line\">foot below the talus, disruption of the talonavicular joint on lateral view</div><div class=\"answer-line\"><strong>Q &amp; A – 2025.1 Fellowship Written Exam – Network 2</strong></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">1.<strong> Consent, Analgesia &amp; Sedation</strong>: IV analgesia + procedural sedation.</div><div class=\"answer-line\">2.<strong> Closed Reduction</strong> – Aware that reasonable failure rate –</div><div class=\"answer-line\">3.<strong> Early Orthopaedic involvement</strong>.</div><div class=\"answer-line\">Place ankle in plantarflexion</div><div class=\"answer-line\">o</div><div class=\"answer-line\">Firm longitudinal traction on the foot with countertraction on</div><div class=\"answer-line\">o</div><div class=\"answer-line\">the leg with Knee flexed 90 degrees to reduce gastrocnemius/</div><div class=\"answer-line\">Achilles tension on the calcaneum</div><div class=\"answer-line\">Distract the hindfoot and apply direct pressure to talar head</div><div class=\"answer-line\">o</div><div class=\"answer-line\">while inverting to exaggerate the deformity, then Evert the foot</div><div class=\"answer-line\">with digital pressure of the talus to reverse the deformity.</div><div class=\"answer-line\">4.<strong> Post-reduction assessment</strong>:</div><div class=\"answer-line\">Confirm <strong>stability, neurovascular status.</strong></div><div class=\"answer-line\">o</div><div class=\"answer-line\">5. Obtain post-reduction Xray and <strong>CT scan to review for associated </strong></div><div class=\"answer-line\"><strong>injuries</strong>. (e.g., osteochondral fractures, talar process fractures).</div><div class=\"answer-line\">6. Disposition: Admission under Orthopedics</div><div class=\"answer-line\">7.<strong> Immobilization</strong>:</div><div class=\"answer-line\">Place in <strong>Short leg cast – non weightbearing for 4-6 weeks in </strong></div><div class=\"answer-line\">o</div><div class=\"answer-line\"><strong>neutral position (90 degress flexion</strong>.</div><div class=\"answer-line\">DVT Prophylaxis</div><div class=\"answer-line\">o</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td></td><td>Associated fractures – (Talar fractures / navicular fractures /</td></tr><tr><td colspan=\"2\">malleoli fractures, metatarsal fractures, calcaneal fractures)</td></tr><tr><td></td><td><strong>Post-traumatic arthritis</strong></td></tr><tr><td></td><td><strong>Avascular necrosis of the talus</strong></td></tr><tr><td colspan=\"2\"><strong>Chronic instability or stiffness</strong></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":18,"title":"","stemText":"A 2 year old male presents to your rural ED with maternal concerns for lethargy.\nThe parents are South Sudanese and have limited English. He appears pale and lethargic.","parts":[{"id":"a","label":"Part A","prompt":"List three (3) historical features that would concern you for an acute sickle crisis (3 marks) On exam he is pale, lethargic but rousable. He has a distended abdomen.\nHis observations are as follows RR 50 HR 150 SpO2 90% on air. Venous blood gas\n\nresults are as follows\n\npH 7.25 pO2 43 Pco2 43 Lactate 3.4 Glu 8 Hb 44 HCO 20 BE -4"},{"id":"b","label":"Part B","prompt":"Outline your approach to the management of this patient (6 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><em>Any of </em></div><div class=\"answer-line\"><em>Temp &gt; 38°C</em></div><div class=\"answer-line\"><em>Pain inadequately relieved by home measures </em></div><div class=\"answer-line\"><em>Respiratory symptoms (cough, shortness of breath, chest pain, hypoxia</em></div><div class=\"answer-line\"><em>Abdominal pain, distension and/or acute splenic enlargement</em></div><div class=\"answer-line\"><em>Any neurologic symptom or sign – even transient </em></div><div class=\"answer-line\"><em>Significant increase in pallor and/or fatigue/lethargy</em></div><div class=\"answer-line\"><em>Priapism episode lasting &gt; 2 hours</em></div><div class=\"answer-line\"><em>Family or personal history of sickle cell </em></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><strong>Q &amp; A – 2025.1 Fellowship Written Exam – Network 2</strong></div><div class=\"answer-line\"><em>Should state concern for acute splenic sequestration or chest crisis </em></div><div class=\"answer-line\"><em>Transfuse blood asap – would accept O neg immediately </em></div><div class=\"answer-line\"><em>Resus, IV access , FBC, RCC, Group and hold </em></div><div class=\"answer-line\"><em>Apply O2, anything sensible </em></div><div class=\"answer-line\"><em>Accept maintaince fluids post blood x1.5 maintainance </em></div><div class=\"answer-line\"><em>Manage pain – sensible approach should include opiates </em></div><div class=\"answer-line\"><em>D.w tertiary centre/ haem and arrange retrieval – must </em></div><div class=\"answer-line\"><em>Seek and treat any focus of infection</em></div><div class=\"answer-line\"><em>IV antibiotics – broad spectrum</em></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":19,"title":"","stemText":"You are working as in the Emergency Department of a major metropolitan\ntertiary hospital when a 59-year-old male presents to ED with 3 hours of\nincreasing chest pain on a background of 2 days of shortness of breath with minimal exertion.\nHe is GCS 13, groaning and complaining of chest pain. His vital signs on arrival\nare as follows: a HR of 95bpm, 108/55mmHg, SpO2 95% RA, RR 22.","parts":[{"id":"a","label":"Part A","prompt":"Interpret the ECG above (1 mark)"},{"id":"b","label":"Part B","prompt":"Outline four (4) key priorities of your management (4 marks) Later, after review of the patient’s presentation, you notice that the time from presentation of the patient to Triage to a doctor being shown the ECG was around 30 minutes."},{"id":"c","label":"Part C","prompt":"List four (4) key steps you would undertake to prevent or minimise this event\n• ccurring again (4 marks)"}],"propPages":["asset:img8d0bc2722faefb1cbd"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><em>tertiary hospital when a 59yo male presents to ED with 3hrs of increasing chest </em></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><em>pain on a background of 2 days of shortness of breath with minimal exertion.</em></div><div class=\"answer-line\"><em>He is GCS 13, groaning and complaining of chest pain. His vital signs on arrival </em></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><em>are as follows: a HR of 95bpm, 108/55mmHg, SpO2 95% RA, RR 22.</em></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":20,"title":"","stemText":"A 45 year old Korean female presents with severe asthma and is successfully\nintubated in the ED.","parts":[{"id":"a","label":"Part A","prompt":"Describe your initial ventilator settings. (4 marks)"},{"id":"b","label":"Part B","prompt":"Shortly after intubation, on FiO2 100%, she becomes hypoxic to 79%. Outline your actions in response to this. (4 marks)"},{"id":"c","label":"Part C","prompt":"Her family are waiting in a separate room and request an update. State four (4) aspects of culturally-competent care in the ED. (4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Titrate FiO2 to SpO2 95% and above</div><div class=\"answer-line\"></div><div class=\"answer-line\">slow RR 6 - 8</div><div class=\"answer-line\"></div><div class=\"answer-line\">small tidal volume 5 - 8 ml/kg</div><div class=\"answer-line\"></div><div class=\"answer-line\">I:E ratio 1:4 or 1:5 (must have &gt;1:2)</div><div class=\"answer-line\"></div><div class=\"answer-line\">minimal PEEP &lt;5</div><div class=\"answer-line\"></div><div class=\"answer-line\">limit peak insp pressure to &lt;40 if possible</div><div class=\"answer-line\"></div><div class=\"answer-line\"><strong>Q &amp; A – 2025.1 Fellowship Written Exam – Network 2</strong></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">must include: disconnect from ventilator and ventilate by hand</div><div class=\"answer-line\"></div><div class=\"answer-line\">answers must outline seeking and/or treating cause of hypoxia</div><div class=\"answer-line\"></div><div class=\"answer-line\">displacement of ETT: check position</div><div class=\"answer-line\"></div><div class=\"answer-line\">obstruction of ETT: mucous plug, tube kink, suction ETT</div><div class=\"answer-line\"></div><div class=\"answer-line\">auscultate the chest for pneumothorax, decompress with 14G needle</div><div class=\"answer-line\"></div><div class=\"answer-line\">breath stacking – decompress chest manually.</div><div class=\"answer-line\"></div><div class=\"answer-line\">equipment failure: check ventilator circuit</div><div class=\"answer-line\"></div><div class=\"answer-line\">other reasonable actions acceptable</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Taking a cultural history with all patients and their families/carers</div><div class=\"answer-line\"></div><div class=\"answer-line\">Incorporating diverse health beliefs and health priorities into ED care</div><div class=\"answer-line\"></div><div class=\"answer-line\">and management plans</div><div class=\"answer-line\">All patients, their family and/or carer have access to support people</div><div class=\"answer-line\"></div><div class=\"answer-line\">according to their cultural needs</div><div class=\"answer-line\">All patients are given the opportunity to speak to a cultural and/or</div><div class=\"answer-line\"></div><div class=\"answer-line\">religious representative of their choosing</div><div class=\"answer-line\">All patients who do not speak English as a first language are provided</div><div class=\"answer-line\"></div><div class=\"answer-line\">access to a  professional interpreter service and information in their</div><div class=\"answer-line\">primary language, including for Indigenous language speakers</div><div class=\"answer-line\">Other reasonable answers acceptable</div><div class=\"answer-line\"></div><div class=\"answer-line\">Ref ACEM statement on culturally competent care and cultural safety in</div><div class=\"answer-line\">emergency medicine.</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":21,"title":"","stemText":"Britney is a 15-year old who has presented to your metropolitan ED with\nincreasing suicidal thoughts. She tells the triage nurse that her boyfriend Justin, 16, has ended the relationship. They have been having consensual sexual intercourse and she is concerned she may be pregnant. She is unaccompanied and does not want you to inform her parents of her presentation.","parts":[{"id":"a","label":"Part A","prompt":"Outline the components of the HEEADSSS assessment to identify areas of concern for Britney’s safety. (8 marks)"},{"id":"b","label":"Part B","prompt":"Outline 4 (four) factors in her history that may increase her risk of suicide\n(4 marks)"},{"id":"c","label":"Part C","prompt":"She requests emergency contraception.\nOutline 2 (two) different options with relevant time frames available to her (2 marks)"},{"id":"d","label":"Part D","prompt":"She is unaccompanied and does not want you to inform her parents of her request for emergency contraception. Outline your approach to this matter (2 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><strong>Q &amp; A – 2025.1 Fellowship Written Exam – Network 2</strong></div><div class=\"answer-line\">Answer-</div><div class=\"answer-line\">H-  home, family life, changes ie divorce, access to computer/ laptop</div><div class=\"answer-line\">E- education, attendance, bullying, engagement with it, disciplinary issues</div><div class=\"answer-line\">E- Eating and exercise- eating habits, weight change, physical activity</div><div class=\"answer-line\">Activities, hobbies, social activities, access to social media</div><div class=\"answer-line\">D-  Drugs and alcohol</div><div class=\"answer-line\">S- sexuality and gender</div><div class=\"answer-line\">S- suicidality, depression and self harm</div><div class=\"answer-line\">S -  safety, risk taking, involvement in forensic activity etc</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Answer – any of</div><div class=\"answer-line\">S - sex – increased risk if male</div><div class=\"answer-line\">A – age &lt;19, &gt;45</div><div class=\"answer-line\">D- depression or hopelessness</div><div class=\"answer-line\">P- previous attempts or psychiatric admissions</div><div class=\"answer-line\">E- excessive alcohol or drug use</div><div class=\"answer-line\">R- rational thinking loss</div><div class=\"answer-line\">S- separated or single</div><div class=\"answer-line\">O- organised plan</div><div class=\"answer-line\">N- no social support         S- sickness/ comorbidity</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Answer</div><div class=\"answer-line\"><strong>Q &amp; A – 2025.1 Fellowship Written Exam – Network 2</strong></div><div class=\"answer-line\">1. Emergency contraception pill</div><div class=\"answer-line\">Emergency contraception pill is taken orally as soon as you can after an</div><div class=\"answer-line\">episode of unprotected sex. You need to ensure you have had your first</div><div class=\"answer-line\">pill within 72 hours (three days). The sooner you take the pills the more</div><div class=\"answer-line\">effective they are.</div><div class=\"answer-line\">2. IUD (Intra Uterine Device)- Copper</div><div class=\"answer-line\">A IUD is a device inserted by a doctor into the uterus (womb). It needs to</div><div class=\"answer-line\">be inserted within five days of unprotected sex and can be used to</div><div class=\"answer-line\">provide long term contraception. It may not be suitable for some women</div><div class=\"answer-line\">and is not suitable for women who experience frequent changes of</div><div class=\"answer-line\">sexual partners as this increases the risk of pelvic infection.</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Answer.</div><div class=\"answer-line\">Mature minor able to consent or refuse to procedures or treatment if deemed</div><div class=\"answer-line\">to have sufficient understanding and intelligence, can be considered to have</div><div class=\"answer-line\">capacity to do so.</div><div class=\"answer-line\">-</div><div class=\"answer-line\">will not require parental consent. Can also mention Gillick</div><div class=\"answer-line\">competence</div><div class=\"answer-line\">-</div><div class=\"answer-line\">recognition that she is able to make the decision for herself and</div><div class=\"answer-line\">this is within the law in NSW and thus should be provided (unless</div><div class=\"answer-line\">you work somewhere weird where they don’t have it) and then</div><div class=\"answer-line\">you should explain to her how to access it</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":22,"title":"","stemText":"A 25-year-old woman has presented following an intentional aspirin overdose.\nA venous blood gas is obtained\n\npH 7.44 (7.35-7.45)\n\npCO2 15 mmHg (35-45)\n\npO2 40 mmHg\n\nBE -14.0 (-3.0-3.0)\n\nHCO3 10 mmol/L (18-27)\n\nNa 142 mmol/L (133-144)\n\nK 3.1 mmol/L (3.3-4.9)\n\nCl 114 mmol/L (97-110)","parts":[{"id":"a","label":"Part A","prompt":"Identify 2 (two) acid-base abnormalities. Include the biochemical evidence for each\n(2 marks)"},{"id":"b","label":"Part B","prompt":"Describe how you will carry out the process of urinary alkalinisation. (3 marks)"},{"id":"c","label":"Part C","prompt":"List 3 (three) other indications for sodium bicarbonate therapy in overdoses\n(3 marks)"},{"id":"d","label":"Part D","prompt":"Intubation and ventilation are hazardous in aspirin overdose. Explain why this is the case (4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>●Respiratory alkalosis - low CO2</td><td>●HAGMA - anion gap 18, elevated BE</td></tr><tr><td>●NAGMA - Delta Gap 6/14  ?excess chloride</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><strong>Q &amp; A – 2025.1 Fellowship Written Exam – Network 2</strong></div><div class=\"answer-line\">●Correct hypokalaemia.</div><div class=\"answer-line\">●Give 1-2 mmol/kg sodium bicarbonate IV bolus.</div><div class=\"answer-line\">●Commence an infusion of 150 mmol sodium bicarbonate in 850 ml of</div><div class=\"answer-line\">5% dextrose at 250 ml/hour.</div><div class=\"answer-line\">●20 mol of KCl may be added to maintain normokalaemia.</div><div class=\"answer-line\">●Aim for a urinary pH &gt; 7.5.</div><div class=\"answer-line\">●Monitor serum bicarbonate and potassium every 4 hours.</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">●Cardiotoxicity due to TCA poisoning</div><div class=\"answer-line\">●Cardiotoxicity due to non-TCA  sodium channel blockade - lamotrigine,</div><div class=\"answer-line\">propranolol, flecainide</div><div class=\"answer-line\">●Prevention of redistribution of salicylates across the blood-brain barrier</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">In aspirin overdose, patients have a high minute volume due to</div><div class=\"answer-line\">increased central respiratory drive (direct stimulation of resp centre)</div><div class=\"answer-line\">leading to a respiratory alkalosis. In acidaemia, more aspirin is un-</div><div class=\"answer-line\">ionised, favouring movement across the blood-brain barrier into the</div><div class=\"answer-line\">CNS which can precipitate acute deterioration. Aspirin is a weak acid -</div><div class=\"answer-line\">at physiological pH is mostly ionised but as pH falls it shifts to non-</div><div class=\"answer-line\">ionised, less polar and is better able to cross the BBB which is where it is</div><div class=\"answer-line\">most dangerous - CNS effects, cerebral oedema and death</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":23,"title":"","stemText":"A 58 year old male presents with sudden, severe, tearing interscapular pain\nsuspicious for acute aortic dissection\n\nObservations HR 112 bpm, BP 185/105, Sats 98% on air, afebrile","parts":[{"id":"a","label":"Part A","prompt":"List 3 (three) pre-existing clinical conditions and 3 (three) examination findings that\nsuggest a high risk that this is acute aortic dissection (6 marks)"},{"id":"b","label":"Part B","prompt":"Explain the pharmacodynamic properties of beta-blockers that make them an important part of the medical management of aortic dissection (2 marks)"},{"id":"c","label":"Part C","prompt":"List 2 (two) beta blockers recommended for use in aortic dissection. Provide an\ninitial dose regimen. (4 marks)"},{"id":"d","label":"Part D","prompt":"The negative likelihood ratio (LR) of a negative D-dimer in aortic dissection is thought to be approximately 0.1. If the pre-test probability of aortic dissection (based\n• n clinical assessment) is low (say, 15%) explain, using examples, why this is (or is\nnot) sufficient to remove the need for further work-up. (3 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Clinical conditions</div><div class=\"answer-line\">●Recent aortic manipulation/instrumentation e,g, PCI</div><div class=\"answer-line\">●Known aortic valve disease</div><div class=\"answer-line\">●Known thoracic aortic aneurysm</div><div class=\"answer-line\">●Marfan’s</div><div class=\"answer-line\">Examination features</div><div class=\"answer-line\">●Focal neuro deficit in conjunction with pain</div><div class=\"answer-line\">●Hypotension/shock</div><div class=\"answer-line\">●New aortic valve murmur</div><div class=\"answer-line\">●Pulse deficit</div><div class=\"answer-line\">●SBP differential b/w arms</div><div class=\"answer-line\"><strong>Q &amp; A – 2025.1 Fellowship Written Exam – Network 2</strong></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Beta blockers reduce adrenoreceptor-mediated contractility - the velocity of</div><div class=\"answer-line\">ventricular contraction (some talk about changing delta-P/delta-T) and so</div><div class=\"answer-line\">reduce the shear stress and mitigate further lesion progression.</div><div class=\"answer-line\">Simply noting they reduce BP is not sufficient to score marks</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><strong>Esmolol </strong>500 mcg/kg IV loading dose over one minute, then initiate IV infusion</div><div class=\"answer-line\">at 25 to 50 mcg/kg per minute; titrate incrementally</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">minutes (maximum 300 mg) <strong>or </strong>0.5 to 2 mg/minute as IV infusion following an</div><div class=\"answer-line\">initial 20 mg IV bolus</div><div class=\"answer-line\"><strong>Metoprolol </strong>5 mg IV bolus every 5 minutes for three doses</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":24,"title":"","stemText":"A 23 year old male presents to your regional emergency department in NSW, 15\nminutes after being bitten by a “big black spider” on his right foot, that he had to shake off. He is nauseous, complaining of a headache and palpitations. He is agitated with complaints of pain to his right foot.\nHis observations are as follows:\n\nGCS 15, Temp 36.9, RR 22, sats 95% RA, HR 124bpm (regular), BP 165/90\nHe has no PMHx of note, is on no regular medications with no known allergies.","parts":[{"id":"a","label":"Part A","prompt":"List 4 (four) other signs or symptoms, you would look for on history and\nexamination as further clinical evidence of systemic envenomation from a funnel- web spider bite. (4 marks)"},{"id":"b","label":"Part B","prompt":"After taking a further history and systemic examination of this patient, you do suspect funnel web envenomation. Outline your immediate management priorities and treatment of this patient (4 marks)"},{"id":"c","label":"Part C","prompt":"State 2 (two) severe consequences of funnel web envenomation that need to be\nconsidered and outline your initial treatment of these. (4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">His observations are as follows:</div><div class=\"answer-line\">GCS 15, Temp 36.9, RR 22, sats 95% RA, HR 124bpm (regular), BP 165/90</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">He is nauseous, complaining of a headache and palpitations. He is agitated with complaints</div><div class=\"answer-line\">of pain to his right foot.</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">His observations are as follows:</div><div class=\"answer-line\">GCS 15, Temp 36.9, RR 22, sats 95% RA, HR 124bpm (regular), BP 165/90</div><div class=\"answer-line\">He has no PMHx of note, is on no regular medications with no known allergies.</div><div class=\"answer-line\"><strong>Q &amp; A – 2025.1 Fellowship Written Exam – Network 2</strong></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":25,"title":"","stemText":"A 48-year-old male presents to your outer metropolitan emergency department.\nHe describes having been bitten on hand by a dark coloured snake while moving a log in the garden. He self-presented to ED with a friend, no first aid having been attended at home. He describes nausea, light-headedness & severe pain at the bite site. On initial assessment, he appears pale & diaphoretic with a HR of 150 & BP 140/100.","parts":[{"id":"a","label":"Part A","prompt":"What are your immediate actions? (3 marks)"},{"id":"b","label":"Part B","prompt":"List 4 (four) envenomation syndromes, their primary clinical features and a\nresponsible species of snake. (4 marks)"},{"id":"c","label":"Part C","prompt":"What are the absolute & relative indications for administering antivenom? (4 marks)"},{"id":"d","label":"Part D","prompt":"How is antivenom administered? (2 marks)"},{"id":"e","label":"Part E","prompt":"List three (3) potential risks of giving antivenom (3 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><em>elasticised, applied over the bite site, then distally, then proximally, covering the </em></div><div class=\"answer-line\"><em>whole limb; whilst also immobilising the patient – i.e stretcher or wheelchair to </em></div><div class=\"answer-line\"><em>treatment space. The PIB should be firm and tight, but not impacting on </em></div><div class=\"answer-line\"><em>venous/arterial circulation.</em></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><em>monitoring and the ability to escalate airway/ventilation support if required</em></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"empty-state\">The supplied marking resource did not contain extractable text for this part.</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"empty-state\">The supplied marking resource did not contain extractable text for this part.</div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\"><em>6. Administer 2 vials of </em><em><strong>funnel web antivenom</strong></em><em> – reconstitute each vial with 10ml of </em></td></tr><tr><td colspan=\"2\"><em>water for injection, dilute dose in 100ml 0.9% NaCl or Hartmans, infuse over 20-</em></td></tr><tr><td colspan=\"2\"><em>30mins and monitor for adverse effects (e.g. hypotension, urticaria, bronchospasm); </em></td></tr><tr><td colspan=\"2\"><em>repeat with the 2</em><em>nd</em><em> vial. </em></td></tr><tr><td colspan=\"2\"><em>7. Administer </em><em><strong>pain relief</strong></em><em>: e.g. 1g paracetamol orally, 400mg ibuprofen orally, 2.5mg </em></td></tr><tr><td colspan=\"2\"><em>-10mg IV morphine titrated to pain.</em></td></tr><tr><td colspan=\"2\"><em>8.</em> Administer anti-emetic; e.g ondansetron 4mg IV or s/l</td></tr><tr><td colspan=\"2\"><em>9.</em> Pressure Immobilisation bandage is only removed AFTER administration of funnel</td></tr><tr><td colspan=\"2\">web antivenom</td></tr><tr><td colspan=\"2\">(NO marks should be given for blood tests as these are not required in this type of</td></tr><tr><td colspan=\"2\">envenomation)</td></tr><tr><td>Question 3</td><td>(4 marks)</td></tr><tr><td colspan=\"2\">State 2 severe consequences of funnel web envenomation that need to be considered and</td></tr><tr><td colspan=\"2\">outline your initial treatment of these:</td></tr><tr><td colspan=\"2\">5.</td></tr><tr><td colspan=\"2\">6.</td></tr><tr><td colspan=\"2\"><strong>Q &amp; A – 2025.1 Fellowship Written Exam – Network 2</strong></td></tr><tr><td colspan=\"2\"><em>Potential Answer:</em></td></tr><tr><td colspan=\"2\"><em>1.</em> Severe hypotension may occur due to catecholamine induced myocardial injury –</td></tr><tr><td colspan=\"2\">may require inotropes</td></tr><tr><td colspan=\"2\"><em>2.</em> Severe hypertension may occur – sedation and/or pain relief is 1st line therapy</td></tr><tr><td colspan=\"2\"><em>3.</em> Respiratory failure due to pulmonary oedema  - may require non invasive (or</td></tr><tr><td colspan=\"2\">invasive) ventilation with PEEP</td></tr><tr><td colspan=\"2\"><em>4.</em> Persistent cholinergic features – may require atropine IV and/or benzodiazepines</td></tr><tr><td colspan=\"2\"><strong>Q.25 SAQ Snakebite</strong></td></tr><tr><td colspan=\"2\"><strong>48yo male presents to your outer metropolitan emergency department. </strong></td></tr><tr><td colspan=\"2\"><strong>He describes having been bitten on hand by a dark coloured snake while </strong></td></tr><tr><td colspan=\"2\"><strong>moving a log in the garden. He self-presented to ED with a friend, no first </strong></td></tr><tr><td colspan=\"2\"><strong>aid having been attended at home. He describes nausea, light-headedness </strong></td></tr><tr><td colspan=\"2\"><strong>&amp; severe pain at the bite site. On initial assessment, he appears pale &amp; </strong></td></tr><tr><td colspan=\"2\"><strong>diaphoretic with a HR of 150 &amp; BP 140/100.</strong></td></tr><tr><td colspan=\"2\"><strong>1. What are your immediate actions? (3 marks)</strong></td></tr><tr><td></td><td>Move pt to resus, apply PBI, immobilise limb (sling)</td></tr><tr><td></td><td>Full non-invasive monitoring, bilateral IV access, commence fluid</td></tr><tr><td colspan=\"2\">resuscitation</td></tr><tr><td></td><td>Coagulation studies, D-Dimer &amp; Fibrinogen, EUC/FBC, CK, Troponin</td></tr><tr><td colspan=\"2\">Analgesia, antiemetic</td></tr></tbody></table></div></section></div>","answerExtractionVerified":false,"answerSourceRetained":false},{"number":26,"title":"","stemText":"A 24 year old man is brought to ED after becoming unwell after surfacing from a\nSCUBA dive.","parts":[{"id":"a","label":"Part A","prompt":"List 8 (eight) relevant things which need to be asked in the history. (8 marks)"},{"id":"b","label":"Part B","prompt":"List 4 (four) risk factors for developing decompression illness. (4 marks)"},{"id":"c","label":"Part C","prompt":"List 4 (four) types of barotrauma (4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><strong>Q &amp; A – 2025.1 Fellowship Written Exam – Network 2</strong></div><div class=\"answer-line\">Number of dives</div><div class=\"answer-line\">Depth of dive</div><div class=\"answer-line\">Bottom time (time from beginning descent to direct ascent)</div><div class=\"answer-line\">Safety stop</div><div class=\"answer-line\">Any complications during the dive – eg rapid ascent</div><div class=\"answer-line\">Surface interval between dives</div><div class=\"answer-line\">Time interval between completion of dive and onset of symptoms</div><div class=\"answer-line\">Diving experience</div><div class=\"answer-line\">Gases used in dive (air / nitrox / oxygen in military)</div><div class=\"answer-line\">Dive profile – tables or computer</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Previous DCI</div><div class=\"answer-line\">Cold water</div><div class=\"answer-line\">Heavy exercise during or post dive</div><div class=\"answer-line\">Increasing age</div><div class=\"answer-line\">Multiple ascents</div><div class=\"answer-line\">Repetitive dives</div><div class=\"answer-line\">Exposure to altitude (&gt; 300 m) post dive</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td></td><td>Systemic, non-specific</td></tr><tr><td colspan=\"2\">Nausea, headache, abdominal pain, diarrhoea, vomiting</td></tr><tr><td colspan=\"2\">Black, Tiger, Taipan</td></tr><tr><td></td><td>Cardiovascular</td></tr><tr><td colspan=\"2\">Sudden collapse with spontaneous recovery, cardiac arrest,</td></tr><tr><td colspan=\"2\">hypotension</td></tr><tr><td colspan=\"2\">Brown, Tiger</td></tr><tr><td></td><td>Venom Induced Consumptive Coagulopathy</td></tr><tr><td colspan=\"2\">Prolonged bleeding or bruising at bite site, venepuncture site</td></tr><tr><td colspan=\"2\">Intracranial/gastrointestinal/genitourinary haemorrhage</td></tr><tr><td colspan=\"2\">Brown, Tiger, Taipan</td></tr><tr><td></td><td>Neurotoxic</td></tr><tr><td colspan=\"2\">Ptosis, diplopia, blurred vision</td></tr><tr><td colspan=\"2\">Then bulbar dysfunction, respiratory &amp; limb paralysis</td></tr><tr><td colspan=\"2\">Death Adder, Taipan, Tiger</td></tr><tr><td></td><td>Myotoxic</td></tr><tr><td colspan=\"2\">Myalgias (local or generalised)</td></tr><tr><td colspan=\"2\">Black, Tiger, Taipan</td></tr><tr><td colspan=\"2\"><strong>3. What are the absolute &amp; relative indications for administering </strong></td></tr><tr><td colspan=\"2\"><strong>antivenom? (4 marks)</strong></td></tr><tr><td></td><td>Absolute</td></tr><tr><td colspan=\"2\">Sudden collapse, seizures or cardiac arrest</td></tr><tr><td colspan=\"2\">Abnormal INR</td></tr><tr><td colspan=\"2\">Evidence of paralysis</td></tr><tr><td></td><td>Relative</td></tr><tr><td colspan=\"2\">Systemic symptoms</td></tr><tr><td colspan=\"2\">Leucocytosis</td></tr><tr><td colspan=\"2\">Abnormal APTT</td></tr><tr><td colspan=\"2\">CK &gt; 1000</td></tr><tr><td colspan=\"2\">Upon discussion with your local toxicologist, the decision is made to give</td></tr><tr><td colspan=\"2\">antivenom.</td></tr><tr><td colspan=\"2\"><strong>4. How is antivenom administered? (2 marks)</strong></td></tr><tr><td colspan=\"2\"><strong>Q &amp; A – 2025.1 Fellowship Written Exam – Network 2</strong></td></tr><tr><td colspan=\"2\">1 x vial of antivenom diluted 1:10 in sodium chloride 0.9% or compound sodium lactate</td></tr><tr><td colspan=\"2\">(Hartmann) solution, intravenously over 15 minutes.</td></tr><tr><td colspan=\"2\"><strong>5. What are the potential risks of giving antivenom? (3 marks)</strong></td></tr><tr><td></td><td>Anaphylaxis (5%)</td></tr><tr><td></td><td>Systemic hypersensitivity (20-25%)</td></tr><tr><td></td><td>Serum sickness (one third of patients)</td></tr><tr><td colspan=\"2\">Q.26 Diving SAQ With Answers</td></tr><tr><td colspan=\"2\">A 24 year old man is brought to Ed after becoming unwell after surfacing from</td></tr><tr><td colspan=\"2\">a SCUBA dive.</td></tr><tr><td colspan=\"2\"><strong>Q &amp; A – 2025.1 Fellowship Written Exam – Network 2</strong></td></tr><tr><td colspan=\"2\">Number of dives</td></tr><tr><td colspan=\"2\">Depth of dive</td></tr><tr><td colspan=\"2\">Bottom time (time from beginning descent to direct ascent)</td></tr><tr><td colspan=\"2\">Safety stop</td></tr><tr><td colspan=\"2\">Any complications during the dive – eg rapid ascent</td></tr><tr><td colspan=\"2\">Surface interval between dives</td></tr><tr><td colspan=\"2\">Time interval between completion of dive and onset of symptoms</td></tr><tr><td colspan=\"2\">Diving experience</td></tr><tr><td colspan=\"2\">Gases used in dive (air / nitrox / oxygen in military)</td></tr><tr><td colspan=\"2\">Dive profile – tables or computer</td></tr><tr><td colspan=\"2\">Previous DCI</td></tr><tr><td colspan=\"2\">Cold water</td></tr><tr><td colspan=\"2\">Heavy exercise during or post dive</td></tr><tr><td colspan=\"2\">Increasing age</td></tr><tr><td colspan=\"2\">Multiple ascents</td></tr><tr><td colspan=\"2\">Repetitive dives</td></tr><tr><td colspan=\"2\">Exposure to altitude (&gt; 300 m) post dive</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":27,"title":"","stemText":"An 86 year old male presents to your tertiary ED with severe abdominal pain.\nFollowing initial assessment, you are concerned about acute mesenteric ischaemia.","parts":[{"id":"a","label":"Part A","prompt":"List 4 (four) risk factors for acute mesenteric ischaemia (4 marks)"},{"id":"b","label":"Part B","prompt":"Outline 4 (four) differences in history or exam between acute mesenteric ischaemia\nand ischaemic colitis (3 marks)"},{"id":"c","label":"Part C","prompt":"List 4 (four) investigations you would prioritise with justification (4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">1 mark each</div><div class=\"answer-line\">Stronger risk factors</div><div class=\"answer-line\">Age &gt;60 (will accept older age)</div><div class=\"answer-line\"></div><div class=\"answer-line\">Atrial fibrillation</div><div class=\"answer-line\"></div><div class=\"answer-line\">Recent acute myocardial infarction</div><div class=\"answer-line\"></div><div class=\"answer-line\">Valvular heart disease</div><div class=\"answer-line\"></div><div class=\"answer-line\">Aortic atherosclerosis or aneurysm</div><div class=\"answer-line\"></div><div class=\"answer-line\">Aortoiliac instrumentation or surgery.</div><div class=\"answer-line\"></div><div class=\"answer-line\">Others (weaker answers):</div><div class=\"answer-line\">hypercoagulable states</div><div class=\"answer-line\"></div><div class=\"answer-line\">dehydration</div><div class=\"answer-line\"></div><div class=\"answer-line\">portal hypertension</div><div class=\"answer-line\"></div><div class=\"answer-line\">abdominal infections</div><div class=\"answer-line\"></div><div class=\"answer-line\">blunt abdominal trauma</div><div class=\"answer-line\"></div><div class=\"answer-line\">pancreatitis</div><div class=\"answer-line\"></div><div class=\"answer-line\">splenectomy</div><div class=\"answer-line\"></div><div class=\"answer-line\">malignancy in the portal region.</div><div class=\"answer-line\"></div><div class=\"answer-line\">Ref ECI</div><div class=\"answer-line\"><strong>Q &amp; A – 2025.1 Fellowship Written Exam – Network 2</strong></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Ref ECI</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">12 lead ECG – seek AF</div><div class=\"answer-line\"></div><div class=\"answer-line\">Venous blood gas – elevated or rising lactate suggestive of ischaemic</div><div class=\"answer-line\"></div><div class=\"answer-line\">bowel (though normal does not exclude diagnosis)</div><div class=\"answer-line\">Erect CXR – exclude perforation in pt with severe abdo pain</div><div class=\"answer-line\"></div><div class=\"answer-line\">May say FBC, LFT, EUC, coagulation profile with appropriate</div><div class=\"answer-line\"></div><div class=\"answer-line\">justification.</div><div class=\"answer-line\">CTMA – must include – high sensitivity and specificity diagnosing acute</div><div class=\"answer-line\"></div><div class=\"answer-line\">mesenteric ischaemia</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false}];
